package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		requestHash := hashRequest(ids)
		result := protocol.Result{ApprovedIDs: append([]string(nil), ids...)}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Serialize attempts for the complete idempotency scope. This is needed
		// because the ActionRequest row is deliberately written only on success.
		scope := operation + "\x00" + u.Tenant + "\x00" + u.User + "\x00" + key
		if err = tx.QueryRow(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1, 0))`, scope).Scan(new(any)); err != nil {
			return protocol.Result{}, false, err
		}
		if err = setIdentity(ctx, tx, u); err != nil {
			return protocol.Result{}, false, err
		}

		var storedHash string
		var storedResponse []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash", response FROM "ActionRequest"
			WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse)
		if err == nil {
			if storedHash != requestHash {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			if err = json.Unmarshal(storedResponse, &result); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		}
		if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase"
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3
			AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := make([]string, 0, len(ids))
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		if err = rows.Err(); err != nil {
			rows.Close()
			return protocol.Result{}, false, err
		}
		rows.Close()
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3
			AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest"
			("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6)`,
			u.Tenant, u.User, operation, key, requestHash, response)
		if err != nil {
			return protocol.Result{}, false, err
		}
		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit"
				("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
				VALUES ($1,$2,$3,$4,$5,'submitted','approved')`,
				u.Tenant, id, u.User, operation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func setIdentity(ctx context.Context, tx pgx.Tx, u app.Identity) error {
	_, err := tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),
		set_config('app.user',$2,true),set_config('app.role',$3,true)`,
		u.Tenant, u.User, u.Role)
	return err
}

func hashRequest(ids []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ids {
		_, _ = h.Write([]byte(fmt.Sprintf("%d:", len([]byte(id)))))
		_, _ = h.Write([]byte(id))
	}
	return hex.EncodeToString(h.Sum(nil))
}

var _ = strings.Builder{}

